app taskboard {
  wasp: {
    version: "^0.16.7"
  },
  title: "taskboard",
  db: {
    seeds: [
      import { devSeed } from "@src/seed"
    ]
  }
}

route RootRoute { path: "/", to: MainPage }
page MainPage {
  component: import { MainPage } from "@src/MainPage"
}

query getTasks {
  fn: import { getTasks } from "@src/queries",
  entities: [Task]
}

// Intentionally decoupled: this computed/aggregate query only declares
// Project as its entity, even though it derives data from Task rows via
// the Project -> Task relation. Because of this, Wasp's automatic,
// entity-based cache invalidation will NOT refresh this query when the
// addTask/toggleTask Actions run (they only declare Task). The client is
// responsible for manually invalidating this query's cache after those
// actions succeed.
query getProjectStats {
  fn: import { getProjectStats } from "@src/queries",
  entities: [Project]
}

action addTask {
  fn: import { addTask } from "@src/actions",
  entities: [Task]
}

action toggleTask {
  fn: import { toggleTask } from "@src/actions",
  entities: [Task]
}

// Query: returns every task, with its id, title, done state and project id.
export const getTasks = async (_args, context) => {
  return context.entities.Task.findMany({
    orderBy: { id: 'asc' },
    select: {
      id: true,
      title: true,
      done: true,
      projectId: true,
    },
  })
}

// Computed/derived Query: for every project, returns its id, name, the
// total number of tasks in that project, and the number of done tasks.
//
// NOTE: This query is intentionally declared (in main.wasp) with only the
// `Project` entity, even though the counts below are derived from the
// related `Task` rows. Wasp's automatic cache invalidation only kicks in
// when an Action that shares a declared entity runs, so Actions that only
// touch `Task` (addTask, toggleTask) will NOT automatically refresh this
// query on the client - the client has to invalidate it manually.
export const getProjectStats = async (_args, context) => {
  const projects = await context.entities.Project.findMany({
    orderBy: { id: 'asc' },
    include: {
      tasks: {
        select: { done: true },
      },
    },
  })

  return projects.map((project) => ({
    id: project.id,
    name: project.name,
    totalTasks: project.tasks.length,
    doneTasks: project.tasks.filter((task) => task.done).length,
  }))
}

import { HttpError } from 'wasp/server'

// Action: creates a new task in a given project.
export const addTask = async ({ projectId, title }, context) => {
  if (!projectId) {
    throw new HttpError(400, 'projectId is required')
  }
  if (!title || !title.trim()) {
    throw new HttpError(400, 'title is required')
  }

  return context.entities.Task.create({
    data: {
      title,
      done: false,
      project: { connect: { id: projectId } },
    },
  })
}

// Action: flips a task's done state.
export const toggleTask = async ({ taskId }, context) => {
  if (!taskId) {
    throw new HttpError(400, 'taskId is required')
  }

  const task = await context.entities.Task.findUnique({
    where: { id: taskId },
  })
  if (!task) {
    throw new HttpError(404, 'Task not found')
  }

  return context.entities.Task.update({
    where: { id: taskId },
    data: { done: !task.done },
  })
}

